#include "nanoc/nanoc.h"

// Small file and process helpers for manage.

#include "nanoc/manage.h"
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

// Tells if a path exists.
bool nc_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

// Finds a command on PATH.

static bool nc_search(const char *name, char *out) {
    const char *path = getenv("PATH");
    if (! path) {
        return 0;
    }
    const char * p = path;
    while (*p) {
        const char *end = strchr(p, ':');
        size_t n = end ? (size_t)(end - p) : strlen(p);
        snprintf(out, PATH_MAX, "%.*s/%s", (int)n, n ? p : ".", name);
        if (access(out, X_OK) == 0) {
            return 1;
        }
        p = end ? end + 1 : p + n;
    }
    return 0;
}

// Tells if a command is on PATH.

bool nc_have_command(const char *name) {
    char found[PATH_MAX];
    return nc_search(name, found);
}

// Finds the install prefix of argv0.

bool nc_prefix(const char *argv0, char *out) {
    char exe[PATH_MAX];
    if (strchr(argv0, '/')) {
        if (!realpath(argv0, exe)) {
            return 0;
        }
    } else if (!nc_search(argv0, exe)) {
        return 0;
    }
    char *slash = strrchr(exe, '/');
    if (! slash) {
        return 0;
    }
    *slash = 0;
    slash = strrchr(exe, '/');
    if (! slash) {
        return 0;
    }
    *slash = 0;
    snprintf(out, PATH_MAX, "%s", exe);
    return 1;
}

// Creates a directory tree.

bool nc_make_dirs(const char *path) {
    char copy[PATH_MAX];
    snprintf(copy, sizeof copy, "%s", path);
    for (char *p = copy + 1; *p; ++p) {
        if (*p == '/') {
            *p = 0;
            if (mkdir(copy, 0755) && errno != EEXIST) {
                return 0;
            }
            *p = '/';
        }
    }
    if (mkdir(copy, 0755) && errno != EEXIST) {
        return 0;
    }
    return 1;
}

// Copies one file.

bool nc_copy_file(const char *from, const char *to) {
    FILE *in = fopen(from, "rb");
    if (! in) {
        return 0;
    }
    char dir[PATH_MAX];
    snprintf(dir, sizeof dir, "%s", to);
    char *slash = strrchr(dir, '/');
    if (slash) {
        *slash = 0;
        if (!nc_make_dirs(dir)) {
            fclose(in);
            return 0;
        }
    }
    FILE *out = fopen(to, "wb");
    if (! out) {
        fclose(in);
        return 0;
    }
    char buf[8192];
    bool ok = 1;
    size_t n = fread(buf, 1, sizeof buf, in);
    while (n) {
        if (fwrite(buf, 1, n, out) != n) {
            ok = 0;
        }
        n = fread(buf, 1, sizeof buf, in);
    }
    fclose(in);
    return fclose(out) == 0 && ok;
}

// Asks a yes/no question.

bool nc_confirm(const char *question) {
    printf("%s [y/N] ", question);
    fflush(stdout);
    char line[16];
    if (!fgets(line, sizeof line, stdin)) {
        return 0;
    }
    return line[0] == 'y' || line[0] == 'Y';
}
